#!/usr/bin/env bash
# Codegen drift gate — runnable locally and in CI.
#
# Most per-primitive collection sources are CODE-GENERATED from internal/codegen
# (text/template + go/format). Committed generated files carry a
# "// Code generated by internal/codegen; DO NOT EDIT." banner on their FIRST
# line. This gate deletes every such file, regenerates, and fails on any diff or
# stray/untracked output — keeping the generator the single source of truth
# (edit the template, never the generated file).
#
# Three failure modes are caught:
#   - drift:  a committed file differs from its template      -> git diff
#   - orphan: the templates no longer emit a committed file   -> git diff (stays deleted)
#   - stray:  the templates emit a file that was never committed -> git status
#
# Usage: scripts/check-codegen.sh   (run from the repo root)
set -euo pipefail

cd "$(dirname "$0")/.."

banner='// Code generated by internal/codegen; DO NOT EDIT.'
while IFS= read -r f; do
  if [ "$(head -n 1 "$f")" = "$banner" ]; then rm -f "$f"; fi
done < <(git ls-files '*.go')

go generate ./...

if ! git diff --exit-code; then
  echo "error: generated sources are out of date or orphaned — run 'go generate ./...' and commit the result" >&2
  exit 1
fi

stray="$(git status --porcelain --untracked-files=all)"
if [ -n "$stray" ]; then
  echo "error: 'go generate ./...' produced untracked files:" >&2
  echo "$stray" >&2
  exit 1
fi

echo "codegen drift gate: OK"
